        await commitIfShadow(
          ctx.shadow,
          "task-submit",
          foundTask.slugs[0] || index.shortUlid(foundTask._ulid),
        );
        success(
          `Submitted task for review: ${index.shortUlid(updatedTask._ulid)}`,
