const wf = JSON.parse(fs.readFileSync('/tmp/pr-review-merge.json', 'utf8'));
const updatedSteps = wf.steps.map((step, idx) => {
  if (idx === wf.steps.length - 1 && step.type === 'action') {
    return {
      ...step,
      content: step.content.replace('Use: gh pr merge (prefer merge commit to preserve trailers)', 'Use: gh pr merge --merge --delete-branch')
    };
  }
  return step;
});
const commands = [
  { command: 'meta delete', args: { ref: '@pr-review-merge', confirm: true } },
  {
    command: 'meta add',
    args: {
      type: 'workflow',
      id: wf.id,
      trigger: wf.trigger,
      description: wf.description,
      steps: JSON.stringify(updatedSteps)
    }
  }
];
fs.writeFileSync('/tmp/pr-review-merge-batch.json', JSON.stringify(commands, null, 2));
NODE
kspec batch --file /tmp/pr-review-merge-batch.json

