    initGitRepo(tempDir);
    await fs.writeFile(path.join(tempDir, ".gitignore"), "sessions/\n");
    execSync("git add -A && git commit -m 'init'", { cwd: tempDir, stdio: "pipe" });
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

