    // Wait for "Ralph loop completed" which appears after all cleanup.
    const result = await spawnRalphUntil(
      ["--adapter-cmd", `node ${MOCK_AGENT_PATH}`, "--max-loops", "1", "--max-tasks", "2", "--tasks", "@test-task-pending"],
