    // Wait for "Ralph loop completed" (capital R) which appears after all cleanup.
    const result = await spawnRalphUntil(
      ["--adapter-cmd", `node ${crashAgent}`, "--max-loops", "1", "--max-tasks", "2", "--tasks", "@test-task-pending"],
