    const sessionsDir = path.join(tempDir, "sessions");
    const sessionDirs = await fs.readdir(sessionsDir);
    expect(sessionDirs.length).toBe(1);

    const budgetPath = path.join(sessionsDir, sessionDirs[0], "budget.json");
