    const result = kspec("task start @test-task-pending", tempDir, {
      expectFail: true,
      env: { KSPEC_SESSION_ID: sessionId },
    });

    expect(result.exitCode).toBe(4); // VALIDATION_FAILED
    expect(result.stderr).toContain("budget");
  });

