          setTimeout(() => {
            child.kill("SIGKILL");
            resolve({ output });
          }, 500);
        }
      };
      child.stdout!.on("data", onData);
      child.stderr!.on("data", onData);

      child.on("close", () => {
        if (!resolved) {
          resolved = true;
          resolve({ output });
        }
      });

      // Safety timeout
      setTimeout(() => {
        if (!resolved) {
