    await new Promise<void>((resolve) => {
      const check = () => {
        if (output.includes("Creating ACP session")) {
          resolve();
        } else {
          setTimeout(check, 50);
        }
      };
      check();
      setTimeout(resolve, 5_000);
    });

    // Send the signal
    child.kill(signal);

    // Wait for process to exit
    await new Promise<void>((resolve) => {
      child.on("close", () => resolve());
      setTimeout(() => {
        child.kill("SIGKILL");
        resolve();
      }, 10_000);
    });

