  const gitContent = fs.readFileSync(gitPath, 'utf8').trim();
  if (!gitContent.startsWith('gitdir:')) {
    return { exists: true, healthy: false, reason: '.kspec/.git does not contain gitdir reference' };
  }

  return { exists: true, healthy: true };
}

